'')::jsonb ->> 'targetEntityId' = 'asset-placement' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'operation' = 'patch' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'fields' = '["site"]'::jsonb AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'activePackageRevision' = NULLIF(current_setting('registry.active_package_revision', true), '') AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'targetRecordId' = "record_id"::text AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'phase' = '{"kind":"preparation"}'::jsonb AND NULLIF(current_setting('registry.access_profile', true), '') = 'correction-submitter' AND NULLIF(current_setting('registry.principal', true), '') IS NOT NULL AND NULLIF(current_setting('registry.purpose', true), '') IN ('asset-correction') AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'targetRowBoundaries' = '[]'::jsonb AND EXISTS (
